import { log } from "../logging.js";
import { Signer, } from "@keyhive/keyhive/slim";
import { peerIdFromSigner } from "../utilities.js";
const ACTIVE_DB_KEY = "active-key-pair-2";
async function serializeKeyPair(keyPair) {
    const publicKey = await crypto.subtle.exportKey("jwk", keyPair.publicKey);
    const privateKey = await crypto.subtle.exportKey("jwk", keyPair.privateKey);
    const stringified = JSON.stringify({ publicKey, privateKey });
    return new TextEncoder().encode(stringified);
}
async function deserializeKeyPair(bytes) {
    const decoded = new TextDecoder().decode(bytes);
    const { publicKey: publicKeyStr, privateKey: privateKeyStr } = JSON.parse(decoded);
    const publicKey = await crypto.subtle.importKey("jwk", publicKeyStr, "Ed25519", true, publicKeyStr.key_ops);
    const privateKey = await crypto.subtle.importKey("jwk", privateKeyStr, "Ed25519", true, privateKeyStr.key_ops);
    return { publicKey, privateKey };
}
export async function loadOrCreateSigner(db) {
    let keyPair;
    let signer;
    const maybeKeyPairBytes = await db.load([ACTIVE_DB_KEY]);
    if (maybeKeyPairBytes) {
        keyPair = await deserializeKeyPair(maybeKeyPairBytes);
        signer = await Signer.webCryptoSigner(keyPair);
    }
    else {
        try {
            keyPair = await crypto.subtle.generateKey({
                name: "Ed25519",
            }, true, ["sign", "verify"]);
            signer = await Signer.webCryptoSigner(keyPair);
            await storeActiveKeyPair(keyPair, db);
        }
        catch (error) {
            log.error("[AMRepoKeyhive] Error creating signer: ", error);
            throw error;
        }
    }
    return {
        keyPair: keyPair,
        signer: signer,
    };
}
export async function createActive(keyPair, signer, keyhive) {
    const contactCard = await keyhive.getExistingContactCard();
    // TODO: We can now just get this off of Keyhive. We probably don't need it here anymore
    const individual = await keyhive.individual;
    const peerId = peerIdFromSigner(signer);
    return {
        keyPair: keyPair,
        peerId: peerId,
        signer: signer,
        individual: individual,
        contactCard: contactCard,
    };
}
export async function storeActiveKeyPair(keyPair, db) {
    db.save([ACTIVE_DB_KEY], await serializeKeyPair(keyPair));
}
